package com.cybershield.controller;
import com.cybershield.model.*; import com.cybershield.repository.UserRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController { final UserRepository repo; public UserController(UserRepository r){repo=r;} @GetMapping("/me") public User me(Authentication a){return repo.findByEmail(a.getName()).orElseThrow();} @GetMapping @PreAuthorize("hasRole('ADMIN')") public List<User> all(){return repo.findAll();} @GetMapping("/assignees") public List<User> assignees(){return repo.findAll().stream().filter(u->u.getRole()!=Role.USER&&u.isActive()).toList();} @PatchMapping("/{id}/active") @PreAuthorize("hasRole('ADMIN')") public User active(@PathVariable Long id,@RequestParam boolean value){User u=repo.findById(id).orElseThrow();u.setActive(value);return repo.save(u);} }
